/**
 * @distilled.cloud/questrade -- Questrade SDK for Effect.
 *
 * `./services` is generated by `scripts/generate.ts` from the Smithy model
 * that `scripts/convert.ts` builds from Questrade's API documentation
 * (transcribed into `specs/spec-mirror-questrade/specs/`; Questrade
 * publishes no OpenAPI document). Everything else in this folder is
 * hand-written.
 *
 * @example
 * ```ts
 * import { Effect, Layer } from "effect";
 * import * as FetchHttpClient from "effect/http/FetchHttpClient";
 * import * as Questrade from "@distilled.cloud/questrade";
 *
 * const program = Effect.gen(function* () {
 *   const { accounts } = yield* Questrade.listAccounts({});
 *   const id = accounts?.[0]?.number;
 *   if (id === undefined) return;
 *   return yield* Questrade.getBalances({ id });
 * });
 *
 * program.pipe(
 *   Effect.provide(
 *     Layer.mergeAll(FetchHttpClient.layer, Questrade.CredentialsFromEnv, Questrade.QuestradeProtocol),
 *   ),
 *   Effect.runPromise,
 * );
 * ```
 */
export * from "./credentials.ts";
export * from "./errors.ts";
export * as T from "./traits.ts";
export { QuestradeProtocol, type QuestradeOpError, type QuestradeOpContext } from "./protocol.ts";
export * as Retry from "./retry.ts";
export * from "./services/questrade.ts";
